import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u05")

L(1, "Ele, ela e isso", "hij, zij e het com o verbo «is».",
  ["Usar hij, zij/ze e het", "Descrever estados com «is»: moe, blij, ziek"],
  vocab=[V("v-hij","hij","ele","pronoun"), V("v-zij","zij","ela","pronoun",note="Forma átona: ze. Também significa «eles/elas» (com verbo no plural)."),
         V("v-het-pron","het","isso|ele|ela (coisa)","pronoun",note="Para coisas «het» e para o tempo: het is koud."),
         V("v-moe","moe","cansado","adjective"), V("v-blij","blij","contente","adjective"), V("v-ziek","ziek","doente","adjective")],
  ex=[("Hij is moe.","Ele está cansado."),("Zij is blij.","Ela está contente."),("Het is koud.","Está frio."),("Is ze ziek?","Ela está doente?")],
  gram=[G("g-hij-zij-is","Hij, zij, het + is","Para a 3.ª pessoa do singular, **zijn** dá **is**: hij is, zij is, het is. **Zij** tem uma forma átona, **ze**, muito usada na fala. **Het** refere-se a coisas e aparece em frases sem sujeito real: *het is koud* (está frio).",
    [("Hij is ziek.","Ele está doente."),("Het is laat.","É tarde.")],
    "Em «está frio» o português não tem sujeito; o neerlandês precisa de «het».")],
  review=["v-zijn","v-ik","v-jij","v-is"],
  exs=[
    MC("Como se diz «ela»?", ["*zij","hij|«hij» = ele.","jij|«jij» = tu."], "zij (ou ze) = ela.", ["v-zij"]),
    MA([("hij","ele"),("zij","ela"),("moe","cansado"),("blij","contente"),("ziek","doente")], "Pronomes e estados desta lição.", ["v-hij","v-zij","v-moe","v-blij","v-ziek"]),
    CJ("zijn","hij","Hij ___ moe.", ["is"], "zijn: ik ben, jij bent, hij/zij/het is.", ["v-zijn","v-hij"]),
    TR("nl-pt","Zij is blij.", ["Ela está contente","Ela está feliz"], "«zijn» serve para «ser» e «estar».", ["v-zij","v-blij"]),
    TR("pt-nl","Ele está doente.", ["Hij is ziek"], "Hij + is + adjetivo.", ["v-hij","v-ziek"], bank=["Hij","is","ziek","Zij","ben","moe"]),
    TR("pt-nl","Está frio.", ["Het is koud"], "Sem «het» a frase fica incompleta.", ["v-het-pron","v-koud"]),
    FB("___ is koud vandaag.", ["Het"], "Para o tempo, o sujeito é «het».", ["v-het-pron"], choices=["Het","Hij","Ik"], tr="Hoje está frio."),
    WO("Ela está cansada?", ["Is","ze","moe?"], "Pergunta: o verbo vai para o início.", ["v-zij","v-moe"]),
    FE(["Hij","ben","ziek."], 1, "is", "Com «hij» a forma é «is».", ["v-zijn"]),
    LI("Is hij ziek?", ["Is hij ziek"], "Ele está doente?", "Pergunta de sim/não com o verbo no início.", ["v-hij","v-ziek"]),
  ], diff=1, mins=5)

L(2, "Nós, vocês e eles", "As formas do plural: wij, jullie, zij + zijn.",
  ["Conjugar «zijn» no plural", "Dizer onde estão pessoas e coisas"],
  vocab=[V("v-wij","wij","nós","pronoun",note="Forma átona: we."), V("v-jullie","jullie","vocês","pronoun",note="Plural de jij/je: vocês (informal)."),
         V("v-thuis","thuis","em casa","adverb"), V("v-hier","hier","aqui","adverb"), V("v-daar","daar","ali|lá","adverb"),
         V("v-druk","druk","ocupado|movimentado","adjective",note="Ik ben druk = estou ocupado; het is druk = está cheio de gente.")],
  ex=[("Wij zijn thuis.","Nós estamos em casa."),("Zijn jullie moe?","Vocês estão cansados?"),("Ze zijn daar.","Eles estão ali.")],
  gram=[G("g-zijn-plural","Zijn no plural","No plural usa-se sempre **zijn**: **wij/we zijn**, **jullie zijn**, **zij/ze zijn**. *Jullie* é o «vocês» informal; para várias pessoas em registo formal usa-se também **u** (u bent).",
    [("We zijn hier.","Estamos aqui."),("Jullie zijn laat.","Vocês estão atrasados.")],
    "«Zij» pode ser «ela» ou «eles»: o verbo desfaz a dúvida (zij is / zij zijn).")],
  review=["v-zijn","v-zij","v-moe","v-zijn-plural"],
  exs=[
    MA([("wij","nós"),("jullie","vocês"),("thuis","em casa"),("hier","aqui"),("daar","ali")], "Pronomes do plural e lugares.", ["v-wij","v-jullie","v-thuis","v-hier","v-daar"]),
    CJ("zijn","wij","Wij ___ thuis.", ["zijn"], "Plural: wij zijn, jullie zijn, zij zijn.", ["v-wij","v-zijn-plural"]),
    CJ("zijn","jullie","___ jullie moe?", ["Zijn"], "Na pergunta o verbo vai para o início: Zijn jullie…?", ["v-jullie"]),
    MC("«Zij zijn hier.» Quem está aqui?", ["*Eles/elas","Ela|Com «ela» o verbo seria «is».","Nós|«nós» = wij."], "O verbo no plural (zijn) mostra que «zij» = eles/elas.", ["v-zij","v-hier"]),
    TR("nl-pt","Wij zijn thuis.", ["(Nós )estamos em casa"], "«thuis» = em casa.", ["v-wij","v-thuis"]),
    TR("pt-nl","Vocês estão aqui?", ["Zijn jullie hier"], "Pergunta: verbo + sujeito.", ["v-jullie","v-hier"], bank=["Zijn","jullie","hier?","Is","daar"]),
    FB("Het is ___ in de supermarkt.", ["druk"], "«Het is druk» = está cheio de gente.", ["v-druk"], choices=["druk","thuis","daar"], tr="O supermercado está cheio de gente."),
    FE(["We","is","daar."], 1, "zijn", "Com «we» (nós) a forma é «zijn».", ["v-wij"]),
    LI("Ze zijn daar.", ["Ze zijn daar"], "Eles estão ali.", "«ze» é a forma átona de «zij».", ["v-zij","v-daar"]),
    DL([("Mãe","Waar zijn jullie?","Onde estão vocês?"),("Filha","")], ["*We zijn thuis.","We is thuis.|Com «we» o verbo é «zijn».","Ik ben jullie.|Não faz sentido."], "Responde-se com «we zijn…».", ["v-wij","v-thuis"]),
  ], diff=1, mins=5)

L(3, "Formas fortes e fracas", "jij/je, zij/ze, wij/we: quando usar cada uma.",
  ["Reconhecer as formas átonas dos pronomes", "Usar a forma forte para dar ênfase"],
  vocab=[V("v-echt","echt","mesmo|realmente","adverb",note="Echt? = A sério?"), V("v-ook-niet","ook niet","também não","expression")],
  ex=[("Ben je moe? — Ja, en jij?","Estás cansado? — Sim, e tu?","«jij» com ênfase no contraste."),("We zijn laat!","Estamos atrasados!"),("Echt?","A sério?")],
  gram=[G("g-formas-atonas","Formas átonas","Vários pronomes têm duas formas: **jij/je**, **zij/ze**, **wij/we**. A forma átona (je, ze, we) é a normal na fala e na escrita corrente. A forma forte (jij, zij, wij) usa-se para **dar ênfase ou contrastar**: *Ik ben moe, en jíj?*",
    [("Je bent laat.","Estás atrasado."),("Jíj bent laat, niet ik!","TU é que estás atrasado, não eu!")],
    "É parecido com o português, que omite o pronome normalmente e só o usa para contrastar («eu estou bem, e tu?»).")],
  review=["v-jij","v-zij","v-wij","v-moe","v-ook"],
  exs=[
    MC("Qual é a forma átona de «wij»?", ["*we","wie|«wie» = quem.","ze|«ze» é a forma átona de «zij»."], "wij → we.", ["v-wij"]),
    MA([("je","tu (átono)"),("ze","ela (átono)"),("we","nós (átono)"),("echt","mesmo")], "Formas átonas mais comuns.", ["v-jij","v-zij","v-wij","v-echt"]),
    MC("«Ik ben moe. En jij?» Porque se usa «jij» e não «je»?", ["*Porque há contraste: e TU?","Porque é formal|A forma formal é «u».","Porque é plural|O plural é «jullie»."], "A forma forte marca ênfase ou contraste.", ["v-jij"]),
    TR("nl-pt","Echt?", ["A sério","Mesmo","[A sério|Mesmo|Verdade]"], "«Echt?» mostra surpresa.", ["v-echt"]),
    TR("nl-pt","Ik ook niet.", ["Eu também não"], "«ook niet» = também não.", ["v-ook-niet"]),
    FB("Ik ben niet moe. — Ik ___ .", ["ook niet"], "Para concordar com uma negação: «ik ook niet».", ["v-ook-niet"], choices=["ook niet","ook","echt"], tr="Não estou cansado. — Eu também não."),
    TR("pt-nl","Estás cansada?", ["Ben je moe","Ben jij moe"], "Na fala diz-se normalmente «ben je…?».", ["v-moe"]),
    DL([("Tom","Ik ben moe. En jij?","Estou cansado. E tu?"),("Eva","")], ["*Ik ook!","Jij ook!|Assim estaria a falar do Tom.","Ik ben jij.|Não faz sentido."], "«Ik ook» = eu também.", ["v-ook"]),
    LI("We zijn echt laat!", ["We zijn echt laat"], "Estamos mesmo atrasados!", "«echt» reforça: mesmo, realmente.", ["v-wij","v-echt"]),
    WO("Ela está mesmo doente.", ["Ze","is","echt","ziek"], "«echt» antes do adjetivo.", ["v-zij","v-ziek"]),
  ], diff=2, mins=5)

L(4, "Descrever pessoas", "Adjetivos frequentes com o verbo «zijn».",
  ["Descrever pessoas e coisas com adjetivos", "Usar «heel» e «niet» com adjetivos"],
  vocab=[V("v-lang","lang","alto|comprido","adjective",note="Para pessoas: alto."), V("v-aardig","aardig","simpático","adjective"),
         V("v-jong","jong","jovem|novo","adjective"), V("v-mooi","mooi","bonito","adjective"),
         V("v-moeilijk","moeilijk","difícil","adjective"), V("v-makkelijk","makkelijk","fácil","adjective")],
  ex=[("Mijn collega is heel aardig.","O meu colega é muito simpático."),("Nederlands is niet moeilijk!","O neerlandês não é difícil!"),("Hij is lang en jong.","Ele é alto e jovem.")],
  gram=[G("g-adjetivo-predicativo","Adjetivo depois de «zijn»","Depois de **zijn** o adjetivo **não muda**: *hij is lang*, *zij is lang*, *wij zijn lang*. Para intensificar: **heel** (muito). Para negar: **niet** antes do adjetivo: *het is niet moeilijk*.",
    [("De vrouw is mooi.","A mulher é bonita."),("De mannen zijn aardig.","Os homens são simpáticos.")],
    "Em português o adjetivo concorda em género e número (alto/alta/altos); aqui fica sempre igual depois de «zijn».")],
  review=["v-heel","v-niet","v-collega","v-vrouw","v-man"],
  exs=[
    MA([("lang","alto"),("aardig","simpático"),("jong","jovem"),("mooi","bonito"),("moeilijk","difícil")], "Adjetivos para descrever.", ["v-lang","v-aardig","v-jong","v-mooi","v-moeilijk"]),
    MC("«De vrouwen zijn lang.» Que forma tem o adjetivo?", ["*lang (não muda)","langen|O adjetivo depois de «zijn» não leva terminação.","lange|Não depois de «zijn»."], "Depois de «zijn» o adjetivo fica sempre igual.", ["v-lang"]),
    TR("nl-pt","Nederlands is niet moeilijk.", ["O neerlandês não é difícil","Neerlandês não é difícil"], "«niet» antes do adjetivo nega-o.", ["v-moeilijk","v-niet","v-nederlands"]),
    TR("pt-nl","O meu colega é muito simpático.", ["Mijn collega is heel aardig"], "heel + adjetivo = muito…", ["v-aardig","v-heel"], bank=["Mijn","collega","is","heel","aardig","lang","ben"]),
    FB("Het is niet ___, het is makkelijk!", ["moeilijk"], "moeilijk ≠ makkelijk.", ["v-moeilijk","v-makkelijk"], choices=["moeilijk","mooi","jong"], tr="Não é difícil, é fácil!"),
    FE(["Zij","zijn","aardige."], 2, "aardig", "Depois de «zijn» o adjetivo não leva -e.", ["v-aardig"]),
    LI("De stad is heel mooi.", ["De stad is heel mooi"], "A cidade é muito bonita.", "«mooi» com «oo» longo.", ["v-mooi"]),
    WO("Ele não é alto.", ["Hij","is","niet","lang"], "«niet» antes do adjetivo.", ["v-lang","v-niet"]),
    CO("text","Os meus colegas", "Ik heb twee collega's: Eva en Tom. Eva is jong en heel aardig. Tom is lang. Hij is niet jong, maar hij is ook aardig.",
       [("Como é a Eva?", ["*Jovem e muito simpática","Alta e velha","Difícil"]),("O que têm em comum?", ["*São ambos simpáticos","São ambos jovens","São ambos altos"])],
       "«ook aardig» = também simpático.", ["v-aardig","v-jong","v-lang"]),
    SW("Descreva uma pessoa que conhece com dois adjetivos.", ["[Mijn|De] [vriend|vriendin|collega] is [aardig|lang|jong|mooi] en [aardig|lang|jong|mooi]","[Hij|Zij|Ze] is [heel ]aardig en [lang|jong|mooi]"],
       ["Usa «is» + adjetivo","Liga dois adjetivos com «en»","Os adjetivos não levam -e"], 4, "Modelo: «Mijn vriendin is jong en heel aardig.»", ["v-aardig"]),
  ], diff=2, mins=6)

L(5, "Quem é quem?", "Revisão: todos os pronomes e o verbo zijn.",
  ["Conjugar «zijn» com todos os pronomes", "Escolher entre formas fortes e fracas"],
  ex=[("Ik ben, jij bent, u bent, hij/zij/het is","eu sou … ele/ela é"),("wij zijn, jullie zijn, zij zijn","nós somos, vocês são, eles são")],
  review=["v-ik","v-jij","v-u","v-hij","v-zij","v-wij","v-jullie","v-zijn","v-thuis","v-druk"],
  exs=[
    CJ("zijn","u","___ u meneer Bakker?", ["Bent"], "Com «u»: u bent — também na pergunta (o -t não cai com u).", ["v-u"]),
    CJ("zijn","jij","___ jij thuis?", ["Ben"], "Com «jij» depois do verbo, o -t cai: ben jij…?", ["v-jij"]),
    CJ("zijn","zij (plural)","Zij ___ druk.", ["zijn"], "zij (eles) zijn.", ["v-zij","v-druk"]),
    MA([("ik ben","eu sou"),("hij is","ele é"),("wij zijn","nós somos"),("jullie zijn","vocês são")], "Conjugação de zijn.", ["v-zijn"]),
    MC("Qual é a frase correta?", ["*Bent u moe?","Ben u moe?|Com «u» o verbo mantém o -t: bent u.","Is u moe?|Com «u» usa-se «bent»."], "u bent / bent u…?", ["v-u"]),
    TR("pt-nl","Nós estamos ocupados.", ["[Wij|We] zijn druk"], "«druk» = ocupado.", ["v-wij","v-druk"]),
    TR("nl-pt","Zijn jullie thuis?", ["Vocês estão em casa","Estão em casa"], "jullie = vocês.", ["v-jullie","v-thuis"]),
    FE(["Jullie","is","hier."], 1, "zijn", "«jullie» leva o verbo no plural: zijn.", ["v-jullie"]),
    CO("dialogue","Ao telefone", "Sanne: Hoi Tom! Waar ben je?\nTom: Ik ben thuis. Ik ben ziek.\nSanne: O nee! Is Eva ook thuis?\nTom: Nee, zij is op haar werk.",
       [("Onde está o Tom?", ["*Em casa","No trabalho","Na escola"]),("Porquê?", ["*Está doente","Está cansado","Está contente"]),("E a Eva?", ["*Está no trabalho","Também está em casa","Está doente"])],
       "«op haar werk» = no trabalho dela.", ["v-thuis","v-ziek"]),
    LI("Hij is hier en zij is daar.", ["Hij is hier en zij is daar"], "Ele está aqui e ela está ali.", "hier/daar = aqui/ali.", ["v-hier","v-daar"]),
  ], diff=2, mins=6)

W()
